function styleHeader(header, current){
  header.resize(1440, header.height);
  const items=['Home','Blog','About Us','Contact us'];
  let x=783;
  for(const it of items){
    const t=header.findOne(n=>n.type==='TEXT'&&n.name==='Nav/'+it);
    if(t){ t.x=x; t.y=31; x += t.width + (it==='Home'?0:0) + 32; if(it==='Home'&&current==='Home') x+=0; }
  }
  // spacing: recompute centered group
  const texts=items.map(it=>header.findOne(n=>n.type==='TEXT'&&n.name==='Nav/'+it)).filter(Boolean);
  let total=0; for(const t of texts) total+=t.width; total += 32*(texts.length-1);
  let cx=Math.round((1440-total-196-32)/2);
  for(const t of texts){ t.x=cx; t.y=31; cx+=t.width+32; }
  const btn=header.findOne(n=>n.type==='INSTANCE');
  if(btn){ btn.x=1440-80-btn.width; btn.y=16; }
  const wm=header.findOne(n=>n.type==='TEXT'&&n.name==='Wordmark'); if(wm){wm.x=80;}
  // current marker
  const ct=header.findOne(n=>n.type==='TEXT'&&n.name==='Nav/'+current);
  if(ct){
    ct.fontName={family:'Inter',style:'Semi Bold'};
    const ul=figma.createRectangle(); ul.name='Current Underline';
    ul.resize(Math.max(30,ct.width),3); ul.cornerRadius=1.5; ul.fills=solid(C.yellow);
    header.appendChild(ul); ul.x=ct.x; ul.y=ct.y+ct.height+6;
  }
}

